mapper.select:
SELECT v.id AS resource_version_id, v.resource_key, v.version_no, v.status AS resource_version_status, v.deleted AS resource_version_deleted, v.access_mode, v.exposure_mode, r.resource_name, v.tenant_id AS resource_tenant_id, r.enabled AS resource_enabled, r.status AS resource_status, r.deleted AS resource_deleted FROM agent_execution_resource_version v LEFT JOIN agent_execution_resource r ON r.id = v.resource_id WHERE ( ( v.status = 'PUBLISHED' AND v.deleted = FALSE AND COALESCE(r.deleted, FALSE) = FALSE AND COALESCE(r.enabled, FALSE) = TRUE AND LOWER(COALESCE(r.status, '')) != 'disabled'
AND v.tenant_id = #{tenantId}
AND 1 = 0
AND v.access_mode = 'READ' AND v.exposure_mode = 'MODEL'
AND NOT (v.access_mode = 'WRITE' AND v.exposure_mode = 'MODEL')
)
OR v.id IN #{id}
) ORDER BY COALESCE(r.resource_name, v.resource_key), v.version_no DESC
